const listSessionPackages = `-- name: ListSessionPackages :many
SELECT p.id, p.uuid, p.name, p.description, p.service_id, p.total_sessions, p.price, p.validity_days,
    p.all_branches, p.is_active, p.created_at, p.updated_at,
    s.uuid AS service_uuid, s.name AS service_name,
    (SELECT COUNT(*) FROM customer_packages c
      WHERE c.organization_id = p.organization_id AND c.package_id = p.id)::bigint AS sold_count
FROM session_packages p
JOIN services s ON s.organization_id = p.organization_id AND s.id = p.service_id
WHERE p.organization_id = $1 AND p.deleted_at IS NULL
  AND ($2::boolean IS NULL OR p.is_active = $2::boolean)
  AND ($3::bigint[] IS NULL OR p.service_id = ANY($3::bigint[]))
  AND ($4::bigint IS NULL OR p.all_branches OR EXISTS (
        SELECT 1 FROM session_package_branches pb
         WHERE pb.organization_id = p.organization_id AND pb.package_id = p.id AND pb.branch_id = $4::bigint))
  AND ($5::text IS NULL OR p.name ILIKE '%' || $5 || '%' OR s.name ILIKE '%' || $5 || '%')
ORDER BY
  CASE WHEN $6::text = 'name' AND NOT $7::boolean THEN lower(p.name) END ASC,
  CASE WHEN $6::text = 'name' AND $7::boolean THEN lower(p.name) END DESC,
  CASE WHEN $6::text = 'price' AND NOT $7::boolean THEN p.price END ASC,
  CASE WHEN $6::text = 'price' AND $7::boolean THEN p.price END DESC,
  CASE WHEN $6::text = 'total_sessions' AND NOT $7::boolean THEN p.total_sessions END ASC,
  CASE WHEN $6::text = 'total_sessions' AND $7::boolean THEN p.total_sessions END DESC,
  CASE WHEN $6::text = 'created_at' AND NOT $7::boolean THEN p.created_at END ASC,
  CASE WHEN $6::text = 'created_at' AND $7::boolean THEN p.created_at END DESC,
  lower(p.name) ASC, p.id ASC
LIMIT $9 OFFSET $8
`

