const packageUsageTotals = `-- name: PackageUsageTotals :many
SELECT cp.currency::text AS currency, COUNT(*)::bigint AS used_count,
    COALESCE(SUM(ps.amount), 0)::numeric(14, 2) AS used_amount
FROM package_sessions ps
JOIN customer_packages cp ON cp.organization_id = ps.organization_id AND cp.id = ps.customer_package_id
JOIN reservations r ON r.organization_id = ps.organization_id AND r.id = ps.reservation_id
WHERE ps.organization_id = $1 AND ps.status = 'consumed'
  AND ps.consumed_on BETWEEN $2::date AND $3::date
  AND ($4::bigint[] IS NULL OR r.branch_id = ANY($4::bigint[]))
  AND ($5::bigint[] IS NULL OR r.branch_id = ANY($5::bigint[]))
GROUP BY cp.currency ORDER BY cp.currency
`

type PackageUsageTotalsParams struct {
	OrganizationID  int64       `json:"organization_id"`
	DateFrom        pgtype.Date `json:"date_from"`
	DateTo          pgtype.Date `json:"date_to"`
	BranchIds       []int64     `json:"branch_ids"`
	FilterBranchIds []int64     `json:"filter_branch_ids"`
}

type PackageUsageTotalsRow struct {
	Currency   string         `json:"currency"`
	UsedCount  int64          `json:"used_count"`
	UsedAmount pgtype.Numeric `json:"used_amount"`
}

// Sessions used in the range (their value is service revenue of the
// visits, through the sale lines).
func (q *Queries) PackageUsageTotals(ctx context.Context, arg PackageUsageTotalsParams) ([]PackageUsageTotalsRow, error) {
	rows, err := q.db.Query(ctx, packageUsageTotals,
		arg.OrganizationID,
		arg.DateFrom,
		arg.DateTo,
		arg.BranchIds,
		arg.FilterBranchIds,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PackageUsageTotalsRow{}
	for rows.Next() {
		var i PackageUsageTotalsRow
		if err := rows.Scan(&i.Currency, &i.UsedCount, &i.UsedAmount); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

